package com.asmj.marketplace.service.service;
import com.asmj.marketplace.service.model.*;import com.asmj.marketplace.service.repository.*;import com.asmj.marketplace.category.repository.CategoryRepository;import com.asmj.marketplace.vendor.repository.VendorRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component @RequiredArgsConstructor public class ServiceDataSeeder implements CommandLineRunner{final ServiceListingRepository services;final ProviderScheduleRepository schedules;final VendorRepository vendors;final UserRepository users;final CategoryRepository categories;@Value("${app.seed.enabled:true}")boolean enabled;public void run(String...x){if(!enabled||services.count()>0)return;var v=users.findByEmailIgnoreCase("demo.services@asmj.co.in").flatMap(u->vendors.findByUserId(u.getId())).orElse(null);if(v==null)return;String cid=categories.findAll().stream().filter(c->"Services".equalsIgnoreCase(c.getName())).map(c->c.getId()).findFirst().orElse(null);Instant n=Instant.now();ServiceListing home=save(v.getId(),cid,"Home Appliance Repair","Experienced technicians for AC, refrigerator and washing-machine repair.",List.of("Bengaluru","Mysuru"),List.of(pkg("AC Service",799,60),pkg("Deep Repair Visit",1299,90)));ServiceListing cleaning=save(v.getId(),cid,"Home Deep Cleaning","Professional residential deep-cleaning service.",List.of("Bengaluru"),List.of(pkg("2 BHK",2499,180),pkg("3 BHK",3299,240)));for(ServiceListing s:List.of(home,cleaning))for(DayOfWeek d:DayOfWeek.values())schedules.save(ProviderSchedule.builder().vendorId(v.getId()).serviceId(s.getId()).dayOfWeek(d).startTime(LocalTime.of(9,0)).endTime(LocalTime.of(18,0)).active(d!=DayOfWeek.SUNDAY).build());}
ServiceListing save(String vid,String cid,String name,String desc,List<String> areas,List<ServiceListing.Package> ps){Instant n=Instant.now();return services.save(ServiceListing.builder().vendorId(vid).categoryId(cid).name(name).description(desc).serviceMode("AT_CUSTOMER").serviceAreas(areas).packages(ps).slotDurationMinutes(30).bufferMinutes(15).maxBookingsPerSlot(1).taxRate(5).commissionRate(10).cancellationPolicy(ServiceListing.CancellationPolicy.builder().freeCancellationHours(4).cancellationFeePercent(20).build()).images(List.of("https://placehold.co/800x600/png?text=Service")).active(true).approved(true).featured(true).createdAt(n).updatedAt(n).build());}ServiceListing.Package pkg(String n,double p,int d){return ServiceListing.Package.builder().id(UUID.randomUUID().toString()).name(n).price(p).durationMinutes(d).active(true).build();}}
